using IDSFintech.Api.DTOs; using IDSFintech.Api.Repositories; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace IDSFintech.Api.Controllers;
[ApiController,Authorize,Route("api/[controller]")] public sealed class ClientsController(IPortalRepository r):ControllerBase { [HttpGet] public async Task<IActionResult> All(string? search)=>Ok(new ApiResponse<object>("Clients retrieved.",await r.ClientsAsync(search))); [HttpGet("{id:int}")] public async Task<IActionResult> One(int id)=>await r.ClientAsync(id) is { } x?Ok(new ApiResponse<object>("Client retrieved.",x)):NotFound(new{message="Client not found."}); [HttpPost,Authorize(Roles="CEO,Manager")] public async Task<IActionResult> Add(ClientRequest x){var id=await r.AddClientAsync(x);return CreatedAtAction(nameof(One),new{id},new ApiResponse<object>("Client created.",await r.ClientAsync(id)));} [HttpPut("{id:int}"),Authorize(Roles="CEO,Manager")] public async Task<IActionResult> Edit(int id,ClientRequest x)=>await r.UpdateClientAsync(id,x)?Ok(new{message="Client updated."}):NotFound(new{message="Client not found."}); [HttpDelete("{id:int}"),Authorize(Roles="CEO,Manager")] public async Task<IActionResult> Delete(int id){try{return await r.DeleteClientAsync(id)?NoContent():NotFound(new{message="Client not found."});}catch{return Conflict(new{message="A client with deployments cannot be deleted."});} } }
